SourceCode.Declaration:
/// <summary>
/// Represents a unit conversion item with a conversion factor and descriptive text.
/// </summary>
internal class AVARUMUnitConversionItem
{
    /// <summary>
    /// The conversion factor for the unit of measure.
    /// </summary>
    UnitOfMeasureConversionFactor factor;

    /// <summary>
    /// The descriptive text for the unit of measure conversion.
    /// </summary>
    AVARUMUnitOfMeasureConversionText text;

}

Method.Source:
/// <summary>
/// Initializes a new instance of the <c>AVARUMUnitConversionItem</c> class.
/// </summary>
/// <param name="_factor">The conversion factor.</param>
/// <param name="_text">The descriptive text for the conversion.</param>
public void new(UnitOfMeasureConversionFactor _factor, AVARUMUnitOfMeasureConversionText _text)
{
    this.factor = _factor;
    this.text = _text;
}

/// <summary>
/// Gets the conversion factor.
/// </summary>
/// <returns>The conversion factor.</returns>
public UnitOfMeasureConversionFactor paramFactor()
{
    return this.factor;
}

/// <summary>
/// Gets the descriptive text for the conversion.
/// </summary>
/// <returns>The conversion text.</returns>
public AVARUMUnitOfMeasureConversionText paramText()
{
    return this.text;
}

/// <summary>
/// Constructs a new <c>AVARUMUnitConversionItem</c> instance.
/// </summary>
/// <param name="_factor">The conversion factor.</param>
/// <param name="_text">The descriptive text for the conversion.</param>
/// <returns>A new <c>AVARUMUnitConversionItem</c> object.</returns>
public static AVARUMUnitConversionItem construct(UnitOfMeasureConversionFactor _factor, AVARUMUnitOfMeasureConversionText _text)
{
    var item = new AVARUMUnitConversionItem(_factor, _text);
    return item;
}

/// <summary>
/// Default instance of <c>AVARUMUnitConversionItem</c> with factor 1 and empty text.
/// </summary>
/// <returns>A default <c>AVARUMUnitConversionItem</c> object.</returns>
public static AVARUMUnitConversionItem default()
{
    var item = new AVARUMUnitConversionItem(1, '');
    return item;
}
